INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2575, 'ឡានធ្វើដំណើរពីភ្នំពេញទៅសៀមរាប \(314\ \text{km}\) ចេញម៉ោង \(6\ \text{h}\ 30\ \text{mn}\) ដល់ម៉ោង \(11\ \text{h}\ 00\ \text{mn}\) ដោយឈប់សម្រាក \(30\ \text{mn}\)។ ក. រយៈពេលដើរពិតប្រាកដ។ ខ. ល្បឿនមធ្យមក្នុងរយៈពេលនោះ (km/h)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ពេលសរុប \(4\ \text{h}\ 30\ \text{mn}\) ដក \(30\ \text{mn}\) \(= 4\ \text{h}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2576, 'ដបទឹកក្រូចមួយចំណុះ \(75\ \text{c}\ell\) ថ្លៃ \(2\,500\) ៛។ ក. \(12\) ដបមានចំណុះប៉ុន្មានលីត្រ? ខ. ថ្លៃសរុប? គ. ទឹកក្រូចមួយលីត្រថ្លៃប៉ុន្មានរៀលប្រហែល?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(12 \times 75 = 900\ \text{c}\ell = 9\ \ell\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2577, 'ក្រុមហ៊ុនដឹកអង្ករ \(48\) បាវ ក្នុងមួយបាវ \(50\ \text{kg}\) ដោយឡានម៉ាស់ទទេ \(2.15\ \text{t}\)។ ក. ម៉ាសអង្ករគិតជា t។ ខ. ម៉ាសសរុបនៃឡាន+អង្ករ? គ. ស្ពានអនុញ្ញាតអតិបរមា \(5\ \text{t}\) ឡានឆ្លងបានទេ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(48 \times 50 = 2\,400\ \text{kg} = 2.4\ \text{t}\) (2 ពិន្ទុ)
